import { Table, BooleanColumn, StringColumn, ReferenceColumn, IntegerColumn } from '../../db'

export const sys_ws_version = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    display: 'version_id',
    extends: 'sys_metadata',
    label: 'Scripted REST Version',
    name: 'sys_ws_version',
    schema: {
        active: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Activates this version. Resources belonging to inactive versions cannot serve requests.',
                    label: 'Active',
                    plural: 'Active',
                },
            ],
            maxLength: 30,
        }),
        short_description: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'The description of the version. Appears in API documentation.',
                    label: 'Short description',
                    plural: 'Short descriptions',
                },
            ],
            maxLength: 80,
        }),
        is_default: BooleanColumn({
            label: [
                {
                    hint: 'Whether this version is the default. Resources belonging to the default version can be accessed from either versioned or non-versioned URIs.',
                    label: 'Is default',
                    plural: 'Is defaults',
                },
            ],
            maxLength: 30,
        }),

        web_service_definition: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'delete',
            label: [
                {
                    hint: 'The API this version belongs to',
                    label: 'API definition',
                    plural: 'API definitions',
                },
            ],
            mandatory: true,
            readOnly: true,
            readOnlyOption: 'instance_configured',
            referenceTable: 'sys_ws_definition',
        }),
        version_id: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            dynamicValueDefinitions: {
                type: 'calculated_value',
                calculatedValue: `if (current.version)
	current.version_id = 'v' + current.version;`,
            },
            label: [
                {
                    hint: 'The version identifier used to indicate this version in URIs',
                    label: 'Version ID',
                    plural: 'Version IDs',
                },
            ],
            mandatory: true,
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
        deprecated: BooleanColumn({
            label: [
                {
                    hint: "Deprecates this version. Resources belonging to deprecated versions can serve requests but are identified as 'Deprecated' in API documentation.",
                    label: 'Deprecated',
                    plural: 'Deprecated',
                },
            ],
            maxLength: 30,
        }),
        version: IntegerColumn({
            label: [
                {
                    hint: 'The number of this version',
                    label: 'Version',
                    plural: 'Versions',
                },
            ],
            mandatory: true,
            maxLength: 10,
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
    },
    textIndex: true,
})
